          <a class="auth__navbar-brand" routerLink="/login">
          <img src="../../../assets/logo.svg" alt="EOS" style="height: auto; width: 60px; display: block;">
        </a>
        </div>
      </div>

      <div class="auth__panel-scroll">
        <div class="auth__card">
          <div class="auth__barbell">
            <span class="plate"></span><span class="plate small"></span>
          </div>

          <div *ngIf="!done">
            <div class="auth__head">
              <h1>New password</h1>
              <p>Choose a new password for your account.</p>
            </div>
            <form class="auth-form" novalidate (ngSubmit)="submit()">
