                  <svg class="field__icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="4" y="10" width="16" height="10" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/></svg>
                  <input id="rp-pw" name="password" type="password" [(ngModel)]="password" autocomplete="new-password" required />
                  <button type="button" class="field__toggle" data-for="rp-pw" aria-label="Show password"></button>
                </div>
              </div>
              <div class="field">
                <label for="rp-pw2">Confirm password</label>
                <div class="field__control">
                  <svg class="field__icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="4" y="10" width="16" height="10" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/></svg>
                  <input id="rp-pw2" name="confirm" type="password" [(ngModel)]="confirm" autocomplete="new-password" required />
                  <button type="button" class="field__toggle" data-for="rp-pw2" aria-label="Show password"></button>
                </div>
              </div>
              <span class="field__error" [class.field__error--show]="error">{{ error }}</span>
              <button type="submit" class="auth-form__submit" [disabled]="loading">
                <span class="btn-label">Reset password</span>
              </button>
            </form>
          </div>
          <div *ngIf="done" class="auth__head">
            <h1>Password updated</h1>
            <p>You can now log in with your new password.</p>
          </div>

          <p class="auth__foot">
            Remembered it? <a routerLink="/login">Back to login</a>
          </p>
        </div>
      </div>
    </div>
  </div>
</div>
